    dist_t_s, _ = dijkstra(t, s)

    if dist_s_t == -1:
        return -1

    # Bidirectional Dijkstra
    dist_s = [float('inf')] * n
    dist_t = [float('inf')] * n
    dist_s[s] = 0
    dist_t[t] = 0
    queue_s = [(0, s)]
    queue_t = [(0, t)]
    visited_s = [False] * n
    visited_t = [False] * n

    while queue_s and queue_t:
        d, u = heapq.heappop(queue_s)
        if visited_s[u]:
            continue
        visited_s[u] = True
        if u == t:
            return d
        for v, w in graph[u]:
            if not visited_s[v] and dist_s[v] > dist_s[u] + w:
                dist_s[v] = dist_s[u] + w
                heapq.heappush(queue_s, (dist_s[v], v))

        d, u = heapq.heappop(queue_t)
        if visited_t[u]:
            continue
        visited_t[u] = True
        if u == s:
            return d
        for v, w in graph[u]:
            if not visited_t[v] and dist_t[v] > dist_t[u] + w:
                dist_t[v] = dist_t[u] + w
                heapq.heappush(queue_t, (dist_t[v], v))

    return -1

