def solve(nums, k):
    # Find the minimum and maximum values in nums
    min_val = min(nums)
    max_val = max(nums)

    # Count the frequency of each number
    count = {}
    for num in nums:
        if num in count:
            count[num] += 1
        else:
            count[num] = 1

    # Iterate through the numbers in sorted order to find the k-th smallest
    current = 0
    for num in range(min_val, max_val + 1):
        if num in count:
            current += count[num]
            if current >= k:
                return num
    return -1

def solve(nums, k):
    def counting_sort(arr):
        min_val = min(arr)
        max_val = max(arr)
        count = {}
        for num in arr:
            count[num] = count.get(num, 0) + 1
        result = []
        for i in range(min_val, max_val + 1):
            if i in count:
                result.extend([i] * count[i])
        return result

    sorted_nums = counting_sort(nums)
    return sorted_nums[k - 1]

def solve(height):
    if not height:
        return 0
    n = len(height)
    left = [0] * n
    right = [0] * n
    left[0] = height[0]
    for i in range(1, n):
        left[i] = max(left[i-1], height[i])
    right[-1] = height[-1]
    for i in range(n-2, -1, -1):
        right[i] = max(right[i+1], height[i])
    water = 0
    for i in range(n):
        water += min(left[i], right[i]) - height[i]
    return water

